"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[2281],{22281:e=>{e.exports=JSON.parse('{"meta":{"title":"Niyyah: Turn an Intention into a Small, Steady Step - iMuslim Life","description":"Niyyah turns an intention into a 7-day plan anchored to your prayer times, and Quran Echoes finds scholar-reviewed Quran passages for what\'s on your heart. Free, no ads."},"periods":{"fajr":"Fajr","dhuhr":"Dhuhr","asr":"Asr","maghrib":"Maghrib","isha":"Isha"},"hero":{"eyebrow":"Niyyah","h1":"Turn an intention into a <g>small, steady</g> step.","lede":"Five gentle questions become a seven-day plan woven into the prayers you already pray. And when your heart is heavy, Quran Echoes finds the ayahs that speak to it.","begin":"Begin, bismillah","tryEchoes":"Try Quran Echoes","facts":"Free \xb7 No ads \xb7 Scholar-reviewed \xb7 Works in your browser","scroll":"Scroll: one day, Fajr to Isha","alt":"Niyyah: a mihrab arch with the Bismillah under the night sky"},"hadith":{"text":"\u201cActions are only by intentions.\u201d","src":"Sahih al-Bukhari 1 \xb7 Sahih Muslim 1907"},"steps":[{"t":"Intention","d":"Choose what you want to grow in: patience, closeness to the Quran, gratitude, gentleness at home."},{"t":"Action","d":"One small step of two to fifteen minutes. Small enough to keep on your hardest day."},{"t":"Moment","d":"Anchored to a prayer you already pray, at your own prayer times, so it moves with the seasons."},{"t":"Reflection","d":"A gentle check-in on day three and day seven. Wrong time? Too much? It adjusts in seconds."}],"effortNote":"Completing a routine is effort on our side. Acceptance and results belong to Allah. The plan is a tool, not a measure of your faith.","try":{"eyebrow":"Quran Echoes \xb7 try it now","h2":"What\u2019s on your <e>heart</e>?","lede":"Write a line about what you\u2019re facing, in English, Urdu, Roman Urdu or Arabic. Niyyah answers with a passage from a scholar-reviewed index and a question to sit with. No sign-in. Nothing you type is saved.","placeholder":"For example: I get impatient with my children in the evenings","inputLabel":"Describe your situation","examples":["I keep losing my temper with my kids","mujhe bohat ghussa aata hai","I feel guilty, will Allah forgive me?","My father passed away and it feels heavy","I\u2019m anxious about money and the future"],"listening":"Listening\u2026","find":"Find passages","failed":"Quran Echoes couldn\u2019t be reached just now. It lives at <a>alexa.imuslimlife.com/niyyah</a>, please try there.","crisisH":"Please reach out to someone now.","crisisP":"What you describe sounds serious, and you deserve real support from a person.","rulingEyebrow":"This needs a scholar","rulingH":"Questions of rulings need a qualified person.","rulingP":"Niyyah never gives fatwas. An imam who knows your situation can answer properly.","none":"No close match yet. Try a few more words about how you feel, or what you\u2019re facing.","surah":"Surah","tafsir":"Tafsir","plan":"Turn this into a 7-day plan","missThanks":"Thank you, that helps us improve. Try describing it in other words.","miss":"Not what I meant","shared":"Shared, thank you. It helps us improve Quran Echoes.","share":"Share this question (without your name) to help improve Quran Echoes.","example":"An example","exampleQ":"When did remembrance of Allah last bring you calm?","exampleSrc":"Ar-Ra\u2019d 13:28 \xb7 Translation of the meaning: Marmaduke Pickthall. Arabic: Tanzil Uthmani."},"ayah":{"en":"Who have believed and whose hearts have rest in the remembrance of Allah. Verily in the remembrance of Allah do hearts find rest!","src":"Ar-Ra\u2019d 13:28 \xb7 Translation of the meaning: Marmaduke Pickthall"},"week":{"eyebrow":"Your week","h2":"Each day you show up, <e>a rose opens</e>.","lede":"No streaks to break, no guilt. Missed days simply stay closed buds and the plan continues tomorrow. The sky changes with your own prayer times, from Fajr rose to Isha stars.","label":"A week of roses: five days opened","shots":["Today, at Isha","Your 7-day plan","The same day, at Dhuhr"]},"care":{"eyebrow":"Built with care","h2":"Trustworthy by <e>design</e>.","items":[{"t":"Scholar-reviewed","d":"Every passage, small action and question is reviewed and approved before anyone sees it."},{"t":"Never a fatwa","d":"Questions about rulings are gently sent to a qualified scholar. Niyyah never rules."},{"t":"Nothing invented","d":"No AI writes religious text here. Passages are the Quran itself, with a named translation."},{"t":"Safe","d":"Words about harm or danger bring helplines first, never passages."},{"t":"Private","d":"Your notes are yours alone. Erase everything with one tap."},{"t":"Free, forever","d":"No ads, no subscriptions. Sadaqah jariyah, in sh\u0101\u02be All\u0101h."}]},"faq":{"eyebrow":"Questions","h2":"Good to <e>know</e>.","items":[{"q":"What does \u201cNiyyah\u201d mean?","a":"Niyyah (\u0646\u0650\u064a\u064e\u0651\u0629) is intention. \u201cActions are only by intentions\u201d (Sahih al-Bukhari 1). Niyyah helps an intention become a small, steady action."},{"q":"Do I need an account?","a":"No account is needed to try Quran Echoes. To keep a plan, mark the days you showed up and save passages, sign in with Amazon, the same sign-in as Muslim Companion for Alexa."},{"q":"Which languages does it understand?","a":"English, Urdu, Roman Urdu (like \u201cmujhe bohat ghussa aata hai\u201d) and Arabic. Passages show the Arabic with an English or Urdu translation."},{"q":"Is it a replacement for a scholar or counsellor?","a":"No. Niyyah offers passages to reflect on and small steps to take. For rulings, ask a qualified scholar; in hard times, please reach out to someone you trust or a helpline."},{"q":"Where does it work?","a":"In any browser on your phone, tablet or computer, at alexa.imuslimlife.com/niyyah."}]},"final":{"h2":"Begin with a <g>small</g> step.","lede":"Your first plan takes a minute. May Allah make it easy, and accept it from you.","alexa":"Muslim Companion for Alexa"}}')}}]);